-- Apply one fill: position update and cash movement must live or die together.
-- cash_movements(account_id, amount, memo, created_at) is a small ledger table.
BEGIN;

UPDATE positions
SET    quantity = quantity + 250,
       avg_cost = (avg_cost * quantity + 42.17 * 250) / (quantity + 250)
WHERE  symbol = 'AAPL';

INSERT INTO cash_movements (account_id, amount, memo)
VALUES (7, -10542.50, 'BUY 250 AAPL @ 42.17');

COMMIT;

-- Query: WHERE symbol = ? AND executed_at BETWEEN ? AND ? ORDER BY executed_at
CREATE INDEX idx_fills_symbol_time ON fills (symbol, executed_at);

-- Query: WHERE order_id = ? (foreign key joins and per-order lookups)
CREATE INDEX idx_fills_order ON fills (order_id);
